   7	/**
   8	 * Executor of the method `build-interest-and-indexation-schedule` (v2, after the first independent
   9	 * review). Projects each series period by period with the factors the indentures write: an annual
  10	 * rate accrues exponentially over the period's business days of a 252-day year; a DI series compounds
  11	 * the DI factor with the spread factor; a "p% of DI" series compounds p times the daily DI; an IPCA
  12	 * series updates the nominal by the curve and accrues its spread on the updated nominal. Coupons are
  13	 * paid in cash only in the period that holds a payment date; until then they accrue. Nothing is
  14	 * assumed: a series without terms, payment dates or a matching curve is named as a gap; an
  15	 * amortization schedule that is not in the base leaves the principal projection insufficient; a
  16	 * curve dated elsewhere than the reference date is declared as an assumption. Every factor and
  17	 * amount comes from financial-core or from a traced Decimal operation.
  18	 */
  19	const money = z.string().regex(/^-?\d+(\.\d+)?$/);
  20	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
  21	const rate = z.string().regex(/^-?\d+(\.\d+)?$/);
  22	const nonEmpty = z.string().trim().min(1);
  23	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
  24	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
  25	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
  26	type Anchor = z.infer<typeof anchorSchema>;
  27	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
  28	
  29	export const projectionPeriodSchema = z.object({
  30	  id: nonEmpty,
  31	  start: isoDate,
  32	  end: isoDate,
  33	  /** Business days of the period, from the calendar the base cites (holidays included). */
  34	  businessDays: z.number().int().nonnegative(),
  35	  anchor: anchorSchema,
  36	}).strict();
  37	
  38	export const curveSchema = z.object({
  39	  id: nonEmpty,
  40	  kind: z.enum(["CDI", "IPCA"]),
  41	  /** Annual effective rate applying to each period, as a decimal; the source, its date and anchor are mandatory. */
  42	  annualRateByPeriod: z.record(nonEmpty, rate),
  43	  source: z.object({title: nonEmpty, url: z.string().optional(), asOf: isoDate, anchor: anchorSchema}).strict(),
  44	}).strict();
  45	
  46	export const seriesRemunerationSchema = z.discriminatedUnion("type", [
  47	  z.object({type: z.literal("spread_over_index"), spreadPerYear: rate}).strict(),
  48	  z.object({type: z.literal("percent_of_index"), percentOfIndex: nonNegative}).strict(),
  49	  z.object({type: z.literal("fixed"), ratePerYear: rate}).strict(),
  50	]);
  51	
  52	export const seriesInputSchema = z.object({
  53	  id: nonEmpty,
  54	  label: nonEmpty,
  55	  openingPrincipal: nonNegative,
  56	  indexer: z.enum(["CDI", "IPCA", "fixed", "unknown"]),
  57	  /** Null when the base does not state the remuneration; the series is then a named gap. */
  58	  remuneration: seriesRemunerationSchema.nullable(),
  59	  /** Coupon payment dates inside or beyond the projection; null when the base does not state them. */
  60	  couponDates: z.array(isoDate).nullable(),
  61	  /** Scheduled principal payments; null when the base has no amortization schedule for the series. */
  62	  amortization: z.array(z.object({date: isoDate, amount: nonNegative}).strict()).nullable(),
  63	  /** How indexation is treated; null when the indenture is not in the base (IPCA only). */
  64	  indexationTreatment: z.enum(["capitalized_principal", "cash_paid"]).nullable(),
  65	  curveId: nonEmpty.nullable(),
  66	  anchors: z.object({balance: anchorSchema, terms: anchorSchema.nullable(), payments: anchorSchema.nullable(), amortization: anchorSchema.nullable()}).strict(),
  67	}).strict();
  68	
  69	export const interestScheduleInputSchema = z.object({
  70	  referenceDate: isoDate,
  71	  unit: unitSchema,
  72	  periods: z.array(projectionPeriodSchema).min(1),
  73	  curves: z.array(curveSchema).default([]),
  74	  series: z.array(seriesInputSchema).min(1),
  75	  /** The finance expense of the last closed period, to bridge against; null when not in the base. */
  76	  accountingInterestLastPeriod: z.object({value: money, periodId: nonEmpty, anchor: anchorSchema}).strict().nullable().default(null),
  77	}).strict().superRefine((input, context) => {
  78	  const periodIds = new Set<string>();
  79	  const sorted = [...input.periods].sort((a, b) => compare(a.start, b.start));
  80	  sorted.forEach((period, index) => {
  81	    if (periodIds.has(period.id)) context.addIssue({code: "custom", path: ["periods"], message: `duplicate period ${period.id}`});
  82	    periodIds.add(period.id);
  83	    if (period.end <= period.start) context.addIssue({code: "custom", path: ["periods", index], message: `period ${period.id} ends before it starts`});
  84	    if (index > 0 && sorted[index - 1]!.end !== period.start) context.addIssue({code: "custom", path: ["periods", index], message: `period ${period.id} does not start where ${sorted[index - 1]!.id} ends`});
  85	  });
  86	  if (sorted[0] && sorted[0].start !== input.referenceDate) context.addIssue({code: "custom", path: ["periods", 0], message: "the first period must start at the reference date"});
  87	  const curveIds = new Set<string>();
  88	  for (const curve of input.curves) {
  89	    if (curveIds.has(curve.id)) context.addIssue({code: "custom", path: ["curves"], message: `duplicate curve ${curve.id}`});
  90	    curveIds.add(curve.id);
  91	  }
  92	  const seriesIds = new Set<string>();
  93	  for (const series of input.series) {
  94	    if (seriesIds.has(series.id)) context.addIssue({code: "custom", path: ["series"], message: `duplicate series ${series.id}`});
  95	    seriesIds.add(series.id);
  96	  }
  97	});
