 111	  block_reasons: string[];
 112	  assumptions: string[];
 113	  schedule_by_series: Array<{
 114	    series_id: string; label: string; indexer: string; remuneration: string; curve: {id: string; asOf: string} | null;
 115	    principal_projection: "scheduled" | "insufficient_evidence";
 116	    rows: Row[];
 117	    totals: {cash_interest: string; indexation_capitalized: string; principal_paid: string};
 118	    anchors: {balance: Anchor; terms: Anchor | null; payments: Anchor | null; amortization: Anchor | null};
 119	  }>;
