 121	    by_period: Array<{period: string; cash_interest: string; indexation_capitalized: string; principal_paid: string; closing_principal: string}>;
 122	    by_indexer: Array<{indexer: string; cash_interest: string; indexation_capitalized: string; closing_principal: string; series: string[]}>;
 123	    opening_principal_projected: string;
 124	  } | null;
 125	  accounting_bridge: {projected: string | null; accounting: string; difference: string | null; period: string; anchor: Anchor; state: "compared" | "insufficient_evidence"; reason: string | null} | null;
 126	  uncovered_series: Array<{series_id: string; reason: string; state: "insufficient_evidence"}>;
