 130	const d = (value: Decimal.Value) => new Decimal(value);
 131	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
 132	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
 133	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
