 135	function canonical(input: z.infer<typeof interestScheduleInputSchema>) {
 136	  return {
 137	    ...input,
 138	    periods: [...input.periods].sort((a, b) => compare(a.start, b.start)),
 139	    curves: [...input.curves].sort((a, b) => compare(a.id, b.id)),
 140	    series: [...input.series].sort((a, b) => compare(a.id, b.id)).map((series) => ({...series, couponDates: series.couponDates ? [...series.couponDates].sort(compare) : null, amortization: series.amortization ? [...series.amortization].sort((a, b) => compare(a.date, b.date) || compare(a.amount, b.amount)) : null})),
 141	  };
 142	}
