 144	const describeRemuneration = (series: z.infer<typeof seriesInputSchema>) => {
 145	  const remuneration = series.remuneration!;
 146	  if (remuneration.type === "fixed") return `fixed ${remuneration.ratePerYear} per year`;
 147	  if (remuneration.type === "percent_of_index") return `${remuneration.percentOfIndex} of ${series.indexer}`;
 148	  return `${series.indexer} + ${remuneration.spreadPerYear} per year`;
 149	};
