 151	export function buildInterestAndIndexationSchedule(raw: InterestScheduleInput): InterestScheduleOutput {
 152	  const input = canonical(interestScheduleInputSchema.parse(raw));
 153	  const calculations: Calculation[] = [];
 154	  const record = (calculation: Omit<Calculation, "unit">, unit: string = input.unit) => calculations.push({...calculation, unit});
 155	  const curves = new Map(input.curves.map((curve) => [curve.id, curve]));
 156	  const uncovered: InterestScheduleOutput["uncovered_series"] = [];
 157	  const assumptions = new Set<string>();
 158	  const blockReasons: string[] = [];
 159	  const schedules: InterestScheduleOutput["schedule_by_series"] = [];
 160	  const inPeriod = (date: string, period: {start: string; end: string}) => date > period.start && date <= period.end;
 161	
 162	  for (const series of input.series) {
 163	    if (series.indexer === "unknown" || series.remuneration === null) { uncovered.push({series_id: series.id, reason: `no source in the base states the indexer or the remuneration of ${series.label}`, state: "insufficient_evidence"}); continue; }
 164	    if (!series.anchors.terms) { uncovered.push({series_id: series.id, reason: `the terms of ${series.label} carry no anchor; a term without a source is not a term`, state: "insufficient_evidence"}); continue; }
 165	    if (series.couponDates === null || !series.anchors.payments) { uncovered.push({series_id: series.id, reason: `the payment dates of ${series.label} are not in the base; coupons cannot be placed in time`, state: "insufficient_evidence"}); continue; }
 166	    if ((series.indexer === "CDI" && series.remuneration.type === "fixed") || (series.indexer === "fixed" && series.remuneration.type !== "fixed") || (series.indexer === "IPCA" && series.remuneration.type !== "spread_over_index")) {
 167	      uncovered.push({series_id: series.id, reason: `the remuneration type of ${series.label} (${series.remuneration.type}) does not match its indexer (${series.indexer})`, state: "insufficient_evidence"}); continue;
 168	    }
 169	    const curve = series.curveId ? curves.get(series.curveId) ?? null : null;
 170	    if (series.indexer !== "fixed") {
 171	      if (!curve) { uncovered.push({series_id: series.id, reason: `no registered curve for the ${series.indexer} of ${series.label}; a curve without source and date does not enter`, state: "insufficient_evidence"}); continue; }
 172	      if (curve.kind !== series.indexer) { uncovered.push({series_id: series.id, reason: `curve ${curve.id} is a ${curve.kind} curve and ${series.label} is indexed to ${series.indexer}`, state: "insufficient_evidence"}); continue; }
 173	      if (input.periods.some((period) => curve.annualRateByPeriod[period.id] === undefined)) { uncovered.push({series_id: series.id, reason: `curve ${curve.id} does not cover every projected period`, state: "insufficient_evidence"}); continue; }
 174	      if (curve.source.asOf !== input.referenceDate) assumptions.add(`curve ${curve.id} is dated ${curve.source.asOf}, not the reference date ${input.referenceDate}: the projection uses it as the base scenario and does not call it the curve of the reference date`);
 175	      if (series.indexer === "IPCA") assumptions.add(`IPCA indexation is accrued pro rata by business days from the annual implied inflation of the curve, without the monthly lag of the indenture (declared approximation)`);
 176	    }
 177	    if (series.indexer === "IPCA" && series.indexationTreatment === null) { uncovered.push({series_id: series.id, reason: `the indenture's treatment of the IPCA update (capitalized or paid) is not in the base for ${series.label}`, state: "insufficient_evidence"}); continue; }
 178	    const principalProjection: "scheduled" | "insufficient_evidence" = series.amortization && series.anchors.amortization ? "scheduled" : "insufficient_evidence";
 179	
 180	    let principal = d(series.openingPrincipal);
 181	    let carried = d(0);
 182	    let cashInterest = d(0);
 183	    let capitalized = d(0);
 184	    let principalPaid = d(0);
 185	    const rows: Row[] = [];
 186	    for (const period of input.periods) {
 187	      const opening = principal;
 188	      // 1. Indexation of the nominal (IPCA only), from the curve's annual rate over the period's business days.
 189	      let indexationFactor = d(0);
 190	      if (series.indexer === "IPCA") {
 191	        const accrual = businessDayAccrual(curve!.annualRateByPeriod[period.id]!, period.businessDays);
 192	        indexationFactor = d(accrual.value);
 193	        record({id: `financial.business_day_accrual:${series.id}:${period.id}:indexation`, formula: "(1 + annualRate)^(businessDays/252) - 1", operands: {annualRate: curve!.annualRateByPeriod[period.id]!, businessDays: String(period.businessDays)}, result: accrual.value}, "x");
 194	      }
 195	      const indexationAccrued = principal.times(indexationFactor);
 196	      const indexationCapitalized = series.indexationTreatment === "cash_paid" ? d(0) : indexationAccrued;
 197	      const indexationPaid = series.indexationTreatment === "cash_paid" ? indexationAccrued : d(0);
 198	      principal = principal.plus(indexationCapitalized);
