/bin/bash -lc "pnpm --filter @offroad/credit-playbook exec node <<'NODE'
const Decimal=require('decimal.js'); Decimal.set({precision:50, rounding: Decimal.ROUND_HALF_UP});
const D=x=>new Decimal(x); const fmt=x=>D(x).toDecimalPlaces(8).toFixed();
const bd=(rate,days=63)=>D(1).plus(rate).pow(D(days).div(252)).minus(1).toDecimalPlaces(8);
const ipca=bd('0.06052'); const di=bd('0.1391'); const spreadDi=bd('0.0065'); const diCombined=D(1).plus(di).times(D(1).plus(spreadDi)).minus(1);
console.log(JSON.stringify({factors:{ipca:fmt(ipca),di:fmt(di),spreadDi:fmt(spreadDi),diCombined:fmt(diCombined),crossTerm:fmt(di.times(spreadDi))}},null,2));
const specs=[['deb-13-2','282357','0.063416',[false,true,false,true]],['deb-13-3','110321','0.065264',[false,true,false,true]],['deb-14-2','204059','0.068286',[false,false,true,false]],['deb-14-3','66024','0.069982',[false,false,true,false]],['deb-15-3','50401','0.082',[false,true,false,true]],['deb-15-4','30793','0.087',[false,true,false,true]]];
const schedules=[];
for(const [id,p0,spread,pays] of specs){let p=D(p0),carry=D(0),cash=D(0),cap=D(0); const cf=bd(spread); const rows=[]; for(let q=0;q<4;q++){const opening=p; const idx=p.times(ipca); p=p.plus(idx); const coup=p.plus(carry).times(cf); carry=carry.plus(coup); const paid=pays[q]?carry:D(0); if(pays[q])carry=D(0); cash=cash.plus(paid);cap=cap.plus(idx);rows.push({period:q+1,opening:fmt(opening),idxFactor:fmt(ipca),idx:fmt(idx),couponFactor:fmt(cf),couponAccrued:fmt(coup),couponPaid:fmt(paid),couponCarried:fmt(carry),closing:fmt(p)});} schedules.push({id,rows,totals:{cash:fmt(cash),cap:fmt(cap),closing:fmt(p)}})}
{let p=D('306038'),carry=D(0),cash=D(0);const rows=[]; for(let q=0;q<4;q++){const coup=p.plus(carry).times(diCombined);carry=carry.plus(coup);const pays=q===1||q===3;const paid=pays?carry:D(0);if(pays)carry=D(0);cash=cash.plus(paid);rows.push({period:q+1,opening:fmt(p),couponFactor:fmt(diCombined),couponAccrued:fmt(coup),couponPaid:fmt(paid),couponCarried:fmt(carry),closing:fmt(p)});} schedules.push({id:'deb-13-1',rows,totals:{cash:fmt(cash),cap:'0',closing:fmt(p)}})}
console.log(JSON.stringify(schedules,null,2));
const periods=[];for(let q=0;q<4;q++){let cash=D(0),cap=D(0),close=D(0);for(const s of schedules){cash=cash.plus(s.rows[q].couponPaid);cap=cap.plus(s.rows[q].idx||0);close=close.plus(s.rows[q].closing)}periods.push({period:q+1,cash:fmt(cash),cap:fmt(cap),principalPaid:'0',closing:fmt(close)});}
const byIdx={IPCA:{cash:D(0),cap:D(0),closing:D(0)},CDI:{cash:D(0),cap:D(0),closing:D(0)}};for(const s of schedules){const k=s.id==='deb-13-1'?'CDI':'IPCA';byIdx[k].cash=byIdx[k].cash.plus(s.totals.cash);byIdx[k].cap=byIdx[k].cap.plus(s.totals.cap);byIdx[k].closing=byIdx[k].closing.plus(s.totals.closing)}
console.log(JSON.stringify({aggregate:{opening:specs.reduce((z,x)=>z.plus(x[1]),D('306038')).toFixed(),periods,byIndexer:Object.fromEntries(Object.entries(byIdx).map(([k,v])=>[k,{cash:fmt(v.cash),cap:fmt(v.cap),closing:fmt(v.closing)}]))}},null,2));
NODE"

