118	  objective: z.string().trim().min(1),
119	  product: z.string().trim().min(1),
120	  procedure: z.array(procedureStepSchema).min(1),
121	  output: z.object({schemaId: z.string().regex(/^[a-z][a-z0-9_.-]*$/), fields: z.array(procedureOutputFieldSchema).min(1)}).strict(),
122	  evidence: z.object({
123	    hierarchy: z.array(z.string().trim().min(1)).min(1),
124	    rules: z.array(z.string().trim().min(1)).min(1),
125	    materialClaimsRequireSupport: z.literal(true),
126	  }).strict(),
127	  tests: qualitySchema,
128	  source: z.object({path: z.string().trim().min(1), effectiveDate: z.iso.date(), supersedes: z.string().min(1).optional()}).strict(),
129	  knowledge: z.object({
